// DWT消抖原理与实现

// 1. DWT初始化（使能周期计数器）
void DWT_Init(void) {
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;  // 使能DWT
    DWT->CYCCNT = 0;                                  // 复位计数器
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;             // 使能计数
}

// 2. 定义消抖周期数（50ms @ 168MHz）
// 计算公式：168,000,000 Hz × 0.05 s = 8,400,000
#define DEBOUNCE_CYCLES 8400000

// 3. 消抖检查函数
static uint32_t last_tick = 0;

int is_debounced(void) {
    uint32_t current = DWT->CYCCNT;
    // 检查是否超过消抖周期
    if ((current - last_tick) >= DEBOUNCE_CYCLES) {
        last_tick = current;
        return 1;  // 可以处理
    }
    return 0;  // 仍在消抖中
}

// DWT消抖优势：
// 1. 不阻塞CPU（不使用延时函数）
// 2. 精度高（基于硬件计数器）
// 3. 开销小（仅读取寄存器）

// 档位状态机实现

// 1. 定义状态枚举（顺序很重要）
typedef enum {
    GEAR_P = 0,  // 驻车档
    GEAR_R,       // 倒档
    GEAR_N,       // 空档
    GEAR_D        // 前进档
} GearState_t;

// 2. 当前状态
GearState_t current_gear = GEAR_P;

// 3. 状态切换函数（按键触发）
void Gear_Switch(void) {
    // 方法1: 循环切换
    current_gear = (current_gear + 1) % 4;
    Gear_Update_LED();
}

// 4. LED显示更新
void Gear_Update_LED(void) {
    switch(current_gear) {
        case GEAR_P:  // P: LED0亮，LED1灭
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_SET);
            break;
        case GEAR_R:  // R: LED0灭，LED1亮
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_SET);
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_RESET);
            break;
        case GEAR_N:  // N: 都灭
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_SET);
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_SET);
            break;
        case GEAR_D:  // D: 都亮
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_RESET);
            break;
    }
}

// 思考题：D档如何直接切到R档？
// 答案：实现两段切换
// D档按一次→N档，再按一次→R档

// NVIC优先级配置

// 1. 优先级分组（在main中）
HAL_NVIC_SetPriorityGrouping(NVIC_PRIORITYGROUP_4);  // 4位抢占，0位响应

// 2. 设置EXTI4优先级
HAL_NVIC_SetPriority(EXTI4_IRQn, 5, 0);  // 抢占5，响应0

// 3. 使能中断
HAL_NVIC_EnableIRQ(EXTI4_IRQn);

// 优先级说明：
// - 数值越小，优先级越高
// - 抢占优先级：可以打断低优先级中断
// - 响应优先级：抢占相同时比较响应

// 中断回调函数实现

// HAL库中的弱定义（在stm32f4xx_hal_gpio.c）
__weak void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin) {
    // 默认为空，用户可以重写
}

// 用户代码中重写
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin) {
    // 检查是否是KEY0按键
    if (GPIO_Pin == KEY0_Pin) {
        // 消抖检查
        if (is_debounced()) {
            // 执行状态切换
            Gear_Switch();
        }
    }
}

// 中断响应流程：
// 1. 按键按下触发EXTI中断
// 2. 进入EXTI4_IRQHandler()
// 3. HAL库处理清除中断标志
// 4. 调用HAL_GPIO_EXTI_Callback()
// 5. 执行用户代码

// 时钟配置

// 1. 系统时钟配置（由CubeMX生成）
// System Clock Config = 168MHz
// HCLK (AHB) = 168MHz
// PCLK1 (APB1) = 42MHz
// PCLK2 (APB2) = 84MHz

// 2. 使能GPIO时钟
__HAL_RCC_GPIOE_CLK_ENABLE();  // 使能GPIOE时钟（PE4）
__HAL_RCC_GPIOF_CLK_ENABLE();  // 使能GPIOF时钟（PF9/PF10）

// 注意：必须先使能时钟才能配置GPIO
// 时钟未使能会导致GPIO不工作

